structureEvidence.animationCss:
@-webkit-keyframes bpx-animation-loading { 
  0% { background-position: 0px 0px; }
  6.25% { background-position: -320px 0px; }
  12.5% { background-position: -640px 0px; }
  18.75% { background-position: -960px 0px; }
  25% { background-position: -1280px 0px; }
  31.25% { background-position: -1600px 0px; }
  37.5% { background-position: -1920px 0px; }
  43.75% { background-position: -2240px 0px; }
  50% { background-position: -2560px 0px; }
  56.25% { background-position: -2880px 0px; }
  62.5% { background-position: -3200px 0px; }
  68.75% { background-position: -3520px 0px; }
  75% { background-position: -3840px 0px; }
  81.25% { background-position: -4160px 0px; }
  87.5% { background-position: -4480px 0px; }
  93.75% { background-position: 0px -184px; }
  100% { background-position: -320px -184px; }
}
@keyframes bpx-animation-loading { 
  0% { background-position: 0px 0px; }
  6.25% { background-position: -320px 0px; }
  12.5% { background-position: -640px 0px; }
  18.75% { background-position: -960px 0px; }
  25% { background-position: -1280px 0px; }
  31.25% { background-position: -1600px 0px; }
  37.5% { background-position: -1920px 0px; }
  43.75% { background-position: -2240px 0px; }
  50% { background-position: -2560px 0px; }
  56.25% { background-position: -2880px 0px; }
  62.5% { background-position: -3200px 0px; }
  68.75% { background-position: -3520px 0px; }
  75% { background-position: -3840px 0px; }
  81.25% { background-position: -4160px 0px; }
  87.5% { background-position: -4480px 0px; }
  93.75% { background-position: 0px -184px; }
  100% { background-position: -320px -184px; }
}
@keyframes fly { 
  0% { transform: translateY(0px); }
  50% { transform: translateY(5px); }
  100% { transform: translateY(0px); }
}
@keyframes eat-haha-up { 
  0% { transform: rotate(0deg); }
  25% { transform: rotate(-45deg); }
  50% { transform: rotate(0deg); }
  75% { transform: rotate(-45deg); }
  100% { transform: rotate(0deg); }
}
@keyframes eat-haha-down { 
  0% { transform: rotate(0deg); }
  25% { transform: rotate(45deg); }
  50% { transform: rotate(0deg); }
  75% { transform: rotate(45deg); }
  100% { transform: rotate(0deg); }
}
@keyframes fly { 
  0% { transform: translate(-50%, -25px); }
  50% { transform: translate(-50%, -20px); }
  100% { transform: translate(-50%, -25px); }
}
@keyframes living-status { 
  0% { height: 4px; }
  100% { height: 9px; }
}
@keyframes locmoveclipslider { 
  0% { transform: translateY(0px); }
  5% { transform: translateY(-57px); }
  50% { transform: translateY(-57px); }
  55% { transform: translateY(-110px); }
  100% { transform: translateY(-110px); }
}
@keyframes jump { 
  0% { transform: translateY(0px); }
  50% { transform: translateY(-3px); }
  100% { transform: translateY(0px); }
}
@-webkit-keyframes bili-avatar { 
  0% { transform: translate(0px); }
  100% { transform: translate(-97.5%); }
}
@keyframes bili-avatar { 
  0% { transform: translate(0px); }
  100% { transform: translate(-97.5%); }
}
@keyframes jump { 
  0% { transform: translateY(0px); }
  50% { transform: translateY(-3px); }
  100% { transform: translateY(0px); }
}
@keyframes becomeLarge { 
  0% { transform: scale(1); }
  100% { transform: scale(2.1) translateY(20px) translate(-3px); }
}
@keyframes becomeSmall { 
  0% { transform: scale(2.1) translateY(20px) translate(-3px); }
  100% { transform: scale(1) translateY(0px); }
}
@keyframes hasPendantBecomeSmall { 
  0% { transform: scale(1.8) translateY(20px) translate(-3px); }
  100% { transform: scale(1); }
}
@keyframes hasPendantBecomeLarge { 
  0% { transform: scale(1); }
  100% { transform: scale(1.8) translateY(20px) translate(-3px); }
}
@keyframes showFixeHeader { 
  0% { transform: translateY(-60px); }
  100% { transform: translateY(0px); }
}

